SELECT p.id, p.name FROM product_info p INNER JOIN project_info pi ON p.id=pi.product_id left JOin (select pt.product_id, COALESCE(min(pp.seq),max(ppe.seq)) as seq from project_task pt left join project_phase pp on pt.phase_id = pp.id and pt.product_id = pp.product_id and pt.status in (0,1,2,3,7,9,10) AND pp.is_deleted = FALSE left join project_phase ppe on pt.phase_id = ppe.id and pt.product_id = ppe.product_id and pt.status = 4 AND ppe.is_deleted = FALSE WHERE pt.is_deleted = FALSE GROUP BY pt.product_id) pp on p.id = pp.product_id left join project_phase pph on pp.product_id = pph.product_id and pp.seq = pph.seq AND pph.is_deleted = FALSE WHERE P.delete_state=0 AND p.is_finished_product_dev = 1 AND p.is_deleted = FALSE
AND P.category_id = #{params.categoryId}
AND pph.name = #{params.phaseName}
AND (P.name LIKE concat('%',#{params.searchKeyword},'%') OR p.id IN (SELECT pd.product_id FROM product_detail pd WHERE pd.sku_no LIKE concat('%',#{params.searchKeyword},'%')) OR p.spu_no LIKE concat('%',#{params.searchKeyword},'%'))
AND pi.project_status IN
#{state}
AND P.id IN
#{productId}
